package android.os;import java.util.concurrent.ConcurrentLinkedQueue;
public final class Handler {private static final class Task {final Handler owner;final Runnable work;Task(Handler h,Runnable r){owner=h;work=r;}}private static final ConcurrentLinkedQueue<Task> tasks=new ConcurrentLinkedQueue<>();public Handler(Looper l){}public boolean post(Runnable r){tasks.add(new Task(this,r));return true;}public void removeCallbacksAndMessages(Object token){tasks.removeIf(t->t.owner==this);}public static void drain(){Task t;while((t=tasks.poll())!=null)t.work.run();}public static boolean pending(){return !tasks.isEmpty();}}
